<?php
 namespace App\Library; class Response { public static function json($data = [], $status = 200, array $headers = [], $options = 0) { return response() ->json($data, $status, $headers, $options); } public static function success($data = []) { return self::json(['message' => 'success', 'data' => $data]); } public static function fail($msg = 'fail', $data = []) { return self::json(['message' => $msg, 'data' => $data], 500); } public static function forbidden($msg = 'forbidden', $data = []) { return self::json(['message' => $msg, 'data' => $data], 403); } }